SELECT L.SEGMENT3 AS CODE, L.SEGMENT4 AS NAME FROM SCM_ADM_LOOKUP_MASTER_DETAIL L WHERE L.LOOKUP_TYPE = 'DM_UI_EDITABLE_MEASURE' AND L.SEGMENT1 = 'DMF0082' AND L.SEGMENT2 = @divisionId AND L.VALID_YN = 'Y' AND L.ATTRIBUTE1 = 'Y' AND ((NVL((SELECT MAX(VMI_YN) FROM SCM_MST_SITE WHERE DIVISION_ID = @divisionId AND SCM_SITE_ID = @scmSiteId), 'N') = 'N' AND L.ATTRIBUTE3 <> 'Y') OR NVL((SELECT MAX(VMI_YN) FROM SCM_MST_SITE WHERE DIVISION_ID = @divisionId AND SCM_SITE_ID = @scmSiteId), 'N') = 'Y') AND L.SEGMENT3 NOT IN (CASE WHEN @bucketType = 'D' THEN 'LOC' ELSE CHR(0) END) ORDER BY L.DISPLAY_SEQ